// === Tab: mySketch.js ===
// By 创意编程Oliver
// Transformed into a transparent overlay above image by noel

const MAX_PARTICLE_COUNT = 30;  

const colorScheme1 = "#E69F66"; 
const colorScheme2 = "#ff2b2a";  
const colorScheme3 = "#2276bf";  

let theShader;
let img;
let particleList = [];
let particleGroup;

function preload() {
  theShader = loadShader('https://openprocessing.org/sketch/2397510/files/shader.vert', 'shader.frag'); 
  img = loadImage('https://openprocessing.org/sketch/2397510/files/imageshader.png');
}

function setup() {
  createCanvas(1080, 720, WEBGL);
  noStroke();

  // Create particles in three groups based on color schemes
  // Group 1 (Orange)
  for (let i = 0; i < MAX_PARTICLE_COUNT; i++) {
    const c1 = color(colorScheme1);
    particleList.push(new Particle(width / 2, height / 2, 1000, 1000, c1));
  }

  // Group 2 (Red)
  for (let i = 0; i < MAX_PARTICLE_COUNT; i++) {
    const c2 = color(colorScheme2);
    particleList.push(new Particle(width / 2, height / 2, 3000, 3000, c2));
  }

  // Group 3 (Blue)
  for (let i = 0; i < MAX_PARTICLE_COUNT; i++) {
    const c3 = color(colorScheme3);
    particleList.push(new Particle(width / 2, height / 2, -6000, 6000, c3));
  }

  particleGroup = new ParticleGroup();
}

function draw() {
  shader(theShader);

  // Pass the canvas resolution and image texture to the shader
  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_texture", img);

  // Move particles and get particle data for the shader
  const data = particleGroup.draw();

  // Pass particle data to the shader
  theShader.setUniform("particles", data.particles);
  theShader.setUniform("particleCount", data.particles.length / 3);  // Each particle has 3 values
  theShader.setUniform("particleColors", data.particleColors);

  // Draw the full-screen rectangle with the shader applied
  beginShape();
  vertex(0, 0, 0);              
  vertex(width, 0, 0);        
  vertex(width, height, 0);      
  vertex(0, height, 0);         
  endShape(CLOSE);
}


// === Tab: shader.vert ===

#ifdef GL_ES
precision mediump float;
#endif

attribute vec4 aPosition;  // The position of each vertex
varying vec2 vUv;          // UV coordinates to pass to the fragment shader
uniform vec2 u_resolution; // Canvas resolution

void main() {
    // Map vertex positions to normalized device coordinates (NDC)
    vec2 zeroToOne = aPosition.xy / u_resolution;
    vec2 zeroToTwo = zeroToOne * 2.0;
    vec2 clipSpace = zeroToTwo - 1.0;

    // Pass UV coordinates (range [0, 1]) to the fragment shader
    vUv = zeroToOne;

    // Flip Y-axis to match the p5.js coordinate system
    gl_Position = vec4(clipSpace * vec2(1, -1), 0, 1);
}


// === Tab: shader.frag ===
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform int particleCount; // Number of particles
uniform vec3 particles[90]; // Particle positions and masses
uniform vec3 particleColors[90]; 
uniform sampler2D u_texture; // Image texture
varying vec2 vUv; // UV coordinates from the vertex shader

void main() {
	// Sample the background image using UV coordinates
	vec4 imageColor = texture2D(u_texture, vUv);

	float r = 0.0;
	float g = 0.0;
	float b = 0.0;
	float alpha = 0.0; 

	for (int i = 0; i < 90; i++) {
		// Only process particles up to particleCount
		if (i < particleCount) {
			vec3 particle = particles[i];
			vec2 particlePos = particle.xy; 
			float mass = particle.z; 
			vec3 color = particleColors[i]; 

			// Calculate distance from current fragment to particle
			float dist = distance(vUv, particlePos);

			// Glow intensity (inverse square falloff)
			// float intensity = 0.00003 * mass / (dist * dist);
      float intensity = 0.001 * mass / pow(dist, 1.1);

			// Accumulate particle color values
			r += color.r * intensity;
			g += color.g * intensity;
			b += color.b * intensity;

			// Increase alpha for glowing effect
			alpha += intensity * 0.8;
		}
	}

	// Clamp alpha between 0.0 and 1.0
	alpha = clamp(alpha, 0.0, 1.0);

	// Blend the particles with the background image based on alpha
	vec4 particleColor = vec4(r, g, b, alpha);
	gl_FragColor = mix(imageColor, particleColor, particleColor.a);
}

// === Tab: particle.js ===
class Particle {
  constructor(x, y, noiseXInit, noiseYInit, color) {
    this.pos = new p5.Vector(x, y);  // Start position
    this.vel = p5.Vector.random2D(); // Random initial velocity
    this.vel.mult(random(10));       // Set random initial speed
    this.mass = random(1, 20);   
    this.airDrag = random(0.92, 0.98);  // Air drag factor
    this.color = color;

    // Noise-related values for smooth movement
    this.noiseX = noiseXInit + random(-1.5, 1.5);
    this.noiseY = noiseYInit + random(-1.5, 1.5);
    this.noiseScale = random(0.015, 0.017); 
  }

  move() {
    // Apply Perlin noise for smooth movement
    let x = (noise(this.noiseX) * 2 - 1) * 5;  // wider range !
    let y = (noise(this.noiseY) * 2 - 1) * 5;  
    // Update noise values for continuous movement
    this.noiseX += this.noiseScale;
    this.noiseY += this.noiseScale;

    // Apply the noise to particle movement
    this.pos.add(x, y);

    // Wrap around edges of the canvas to keep particles moving
    if (this.pos.x < 0) this.pos.x = width;
    if (this.pos.x > width) this.pos.x = 0;
    if (this.pos.y < 0) this.pos.y = height;
    if (this.pos.y > height) this.pos.y = 0;
  }
}

function ParticleGroup() {
	this.draw = () => {
		for (let i = 0; i < particleList.length; i++) {
			const p = particleList[i];
			p.move();
		}

		// Return serialized particle data
		return this.serialize();
	};

	this.serialize = () => {
		var data = {
			particles: [],
			particleColors: [],
		};

		// Serialize particle data (positions and colors)
		for (let i = 0; i < particleList.length; i++) {
			var p = particleList[i];
			let itsColor = p.color;

			// Normalize particle positions to [0, 1] for UV mapping
			data.particles.push(
				map(p.pos.x, 0, width, 0.0, 1.0), // Normalize X position
				map(p.pos.y, 0, height, 1.0, 0.0), // Normalize Y position and flip Y-axis
				(p.mass * p.vel.mag()) / 100 // Particle mass/intensity
			);

			// Normalize color components to [0, 1]
			data.particleColors.push(
				red(itsColor) / 255,
				green(itsColor) / 255,
				blue(itsColor) / 255
			);
		}

		return data;
	};
}

